import{_ as t,c as s,o as e,ag as n}from"./chunks/framework.CMajxlqO.js";const g=JSON.parse('{"title":"Hastighetsstyrning","description":"","frontmatter":{},"headers":[],"relativePath":"08-frekvensomriktare/hastighetsstyrning.md","filePath":"08-frekvensomriktare/hastighetsstyrning.md","lastUpdated":1768470380000}'),i={name:"08-frekvensomriktare/hastighetsstyrning.md"};function r(l,a,d,o,h,p){return e(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="hastighetsstyrning" tabindex="-1">Hastighetsstyrning <a class="header-anchor" href="#hastighetsstyrning" aria-label="Permalink to &quot;Hastighetsstyrning&quot;">​</a></h1><p>Hastighetsstyrning av en frekvensomriktare innebär att kontrollera motorns varvtal genom att ändra utfrekvensen. SINAMICS V20 erbjuder flera sätt att sätta och skala hastighetsvärden.</p><h2 id="borvardes-kallor-p1000" tabindex="-1">Börvärdes-källor (P1000) <a class="header-anchor" href="#borvardes-kallor-p1000" aria-label="Permalink to &quot;Börvärdes-källor (P1000)&quot;">​</a></h2><p>Parameter P1000 bestämmer varifrån frekvensomriktaren tar sitt hastighetsvärde:</p><table tabindex="0"><thead><tr><th>P1000 värde</th><th>Källa</th><th>Användning</th></tr></thead><tbody><tr><td>0</td><td>Ingen börvärde</td><td>-</td></tr><tr><td>1</td><td>MOP (BOP potentiometer)</td><td>Manuell justering</td></tr><tr><td>2</td><td>Analog ingång AI1</td><td>0-10V eller 4-20mA</td></tr><tr><td>3</td><td>Fasta frekvenser</td><td>Förprogrammerade steg</td></tr><tr><td>5</td><td>USS-protokoll</td><td>Kommunikation</td></tr><tr><td>6</td><td>Modbus RTU</td><td>Kommunikation</td></tr></tbody></table><h2 id="analog-borvardes-ingang" tabindex="-1">Analog börvärdes-ingång <a class="header-anchor" href="#analog-borvardes-ingang" aria-label="Permalink to &quot;Analog börvärdes-ingång&quot;">​</a></h2><h3 id="konfiguration-av-ai1" tabindex="-1">Konfiguration av AI1 <a class="header-anchor" href="#konfiguration-av-ai1" aria-label="Permalink to &quot;Konfiguration av AI1&quot;">​</a></h3><p>Den analoga ingången kan konfigureras för olika signaltyper:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>P0757 = 0    // 0-10V (standard)</span></span>
<span class="line"><span>P0757 = 2    // 4-20mA</span></span>
<span class="line"><span>P0758 = 0    // Skalning: 0V/4mA = 0 Hz</span></span>
<span class="line"><span>P0760 = 50   // Skalning: 10V/20mA = 50 Hz</span></span></code></pre></div><h3 id="signalskalning" tabindex="-1">Signalskalning <a class="header-anchor" href="#signalskalning" aria-label="Permalink to &quot;Signalskalning&quot;">​</a></h3><p>För att skala analog insignal till önskad frekvens:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Funktion</th></tr></thead><tbody><tr><td>P0758</td><td>Lägsta frekvens vid min signal</td></tr><tr><td>P0760</td><td>Högsta frekvens vid max signal</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">Exempel: Fläktstyrning</p><p>För en fläkt som ska gå 20-50 Hz styrd av 0-10V:</p><ul><li>P0758 = 20 (0V = 20 Hz)</li><li>P0760 = 50 (10V = 50 Hz)</li></ul></div><h2 id="fasta-frekvenser-ff" tabindex="-1">Fasta frekvenser (FF) <a class="header-anchor" href="#fasta-frekvenser-ff" aria-label="Permalink to &quot;Fasta frekvenser (FF)&quot;">​</a></h2><p>Du kan programmera upp till 7 fasta frekvenser som väljs via digitala ingångar:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Funktion</th></tr></thead><tbody><tr><td>P1001</td><td>Fast frekvens 1</td></tr><tr><td>P1002</td><td>Fast frekvens 2</td></tr><tr><td>P1003</td><td>Fast frekvens 3</td></tr><tr><td>...</td><td>...</td></tr><tr><td>P1007</td><td>Fast frekvens 7</td></tr></tbody></table><h3 id="kopplingsschema-for-fasta-frekvenser" tabindex="-1">Kopplingsschema för fasta frekvenser <a class="header-anchor" href="#kopplingsschema-for-fasta-frekvenser" aria-label="Permalink to &quot;Kopplingsschema för fasta frekvenser&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>DI1 + DI2 = Frekvensval:</span></span>
<span class="line"><span>00 = Analog/USS börvärde</span></span>
<span class="line"><span>01 = FF1 (P1001)</span></span>
<span class="line"><span>10 = FF2 (P1002)</span></span>
<span class="line"><span>11 = FF3 (P1003)</span></span></code></pre></div><h2 id="kommunikationsstyrning" tabindex="-1">Kommunikationsstyrning <a class="header-anchor" href="#kommunikationsstyrning" aria-label="Permalink to &quot;Kommunikationsstyrning&quot;">​</a></h2><h3 id="uss-protokoll" tabindex="-1">USS-protokoll <a class="header-anchor" href="#uss-protokoll" aria-label="Permalink to &quot;USS-protokoll&quot;">​</a></h3><p>Med USS-kommunikation skickas börvärdet som ett 16-bitars värde:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Börvärde = (Önskad frekvens / P2000) × 4000 (hex)</span></span></code></pre></div><p><strong>Exempel:</strong> För 25 Hz med P2000 = 50:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Börvärde = (25 / 50) × 16384 = 8192 = 0x2000</span></span></code></pre></div><h3 id="modbus-rtu" tabindex="-1">Modbus RTU <a class="header-anchor" href="#modbus-rtu" aria-label="Permalink to &quot;Modbus RTU&quot;">​</a></h3><p>Med Modbus skrivs frekvens direkt till register:</p><ul><li><strong>Register 40100</strong>: Börvärde i 0.01 Hz (2500 = 25.00 Hz)</li></ul><h2 id="ramper-och-avrundning" tabindex="-1">Ramper och avrundning <a class="header-anchor" href="#ramper-och-avrundning" aria-label="Permalink to &quot;Ramper och avrundning&quot;">​</a></h2><h3 id="grundlaggande-ramper" tabindex="-1">Grundläggande ramper <a class="header-anchor" href="#grundlaggande-ramper" aria-label="Permalink to &quot;Grundläggande ramper&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Parameter</th><th>Funktion</th><th>Typiskt värde</th></tr></thead><tbody><tr><td>P1120</td><td>Uppramptid</td><td>10s</td></tr><tr><td>P1121</td><td>Nedramptid</td><td>10s</td></tr></tbody></table><h3 id="avrundning-s-kurvor" tabindex="-1">Avrundning (S-kurvor) <a class="header-anchor" href="#avrundning-s-kurvor" aria-label="Permalink to &quot;Avrundning (S-kurvor)&quot;">​</a></h3><p>För mjukare acceleration/deceleration:</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Funktion</th></tr></thead><tbody><tr><td>P1130</td><td>Avrundningstid start av ramp</td></tr><tr><td>P1131</td><td>Avrundningstid slut av ramp</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Obs</p><p>Undvik avrundningstider vid analog styrning - det kan orsaka oscillationer. Se <a href="https://support.industry.siemens.com/cs/document/109780402/sinamics-v20-why-does-the-speed-fluctuate-when-i-set-the-setpoint-via-an-analog-input-" target="_blank" rel="noreferrer">Siemens FAQ 109780402</a> för mer information.</p></div><h2 id="praktiskt-exempel-hastighetsstyrning-fran-s7-1200" tabindex="-1">Praktiskt exempel: Hastighetsstyrning från S7-1200 <a class="header-anchor" href="#praktiskt-exempel-hastighetsstyrning-fran-s7-1200" aria-label="Permalink to &quot;Praktiskt exempel: Hastighetsstyrning från S7-1200&quot;">​</a></h2><h3 id="datablock-for-hastighetsvarde" tabindex="-1">Datablock för hastighetsvärde <a class="header-anchor" href="#datablock-for-hastighetsvarde" aria-label="Permalink to &quot;Datablock för hastighetsvärde&quot;">​</a></h3><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// DB för frekvensomriktare</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DATA_BLOCK &quot;DB_V20&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Hastighet_Borvarde : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Real</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Önskad hastighet i Hz</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Hastighet_Aktual : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Real</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;      </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Aktuell hastighet i Hz</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Skalad_Output : Int;          </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Värde till USS/Modbus</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">END_DATA_BLOCK</span></span></code></pre></div><h3 id="skalning-i-scl" tabindex="-1">Skalning i SCL <a class="header-anchor" href="#skalning-i-scl" aria-label="Permalink to &quot;Skalning i SCL&quot;">​</a></h3><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Skala 0-50 Hz till USS-format (0-16384)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&quot;DB_V20&quot;.Skalad_Output := </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    REAL_TO_INT((&quot;DB_V20&quot;.Hastighet_Borvarde / </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">50.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) * </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16384.0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><h2 id="resurser" tabindex="-1">Resurser <a class="header-anchor" href="#resurser" aria-label="Permalink to &quot;Resurser&quot;">​</a></h2><h3 id="officiell-dokumentation" tabindex="-1">Officiell dokumentation <a class="header-anchor" href="#officiell-dokumentation" aria-label="Permalink to &quot;Officiell dokumentation&quot;">​</a></h3><ul><li><a href="https://support.industry.siemens.com/cs/document/109977897/sinamics-v20-converter" target="_blank" rel="noreferrer">SINAMICS V20 Operating Instructions</a> - Komplett parameterreferens</li><li><a href="https://support.industry.siemens.com/cs/document/63696870/sinamics-v-speed-control-of-a-v20-with-s7-1200-(tia-portal)-via-uss-protocol-modbus-rtu-with-hmi" target="_blank" rel="noreferrer">Speed Control V20 with S7-1200 via USS/Modbus</a> - Komplett applikationsexempel med HMI</li></ul><h2 id="nasta-steg" tabindex="-1">Nästa steg <a class="header-anchor" href="#nasta-steg" aria-label="Permalink to &quot;Nästa steg&quot;">​</a></h2><ul><li><a href="./start-stop.html">Start/Stop via PLC</a> - Styra körning från PLC</li><li><a href="./grundparametrar.html">Grundparametrar</a> - Grundkonfiguration</li></ul>`,44)])])}const u=t(i,[["render",r]]);export{g as __pageData,u as default};
